import{_ as a,o as t,c as n,ag as s}from"./chunks/framework.WIXs2PCf.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function o(r,e,l,p,d,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<section class="prompt-hero" aria-labelledby="add-it-to-your-website-in-one-prompt"><div class="prompt-intro"><p class="prompt-eyebrow">FS AI AGENCY <span>/</span> WEBSITE INTEGRATIONS</p><h1 id="add-it-to-your-website-in-one-prompt">Add FSAi to a site<br><span>In one prompt.</span></h1><p class="prompt-description">Funnel or Portal. Your site, your design. Give your agent the prompt.</p></div><div class="agent-prompt"><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a FranchiseAI enquiry flow to this existing website.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Read https://franchiseai.github.io/website-integrations/llms-full.txt and inspect this project&#39;s framework, routes and design system. Identify whether this is a Funnel brand or a Portal brand from the supplied configuration; ask me if it is unclear. Check React 19 compatibility without silently upgrading the site&#39;s framework.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For a Funnel brand: use @franchiseai/website-integrations with its demo adapter and documented qualification controller/hook. Preserve published questions, validation, optional SMS consent, server-controlled outcomes and secure email continuation. Test new and returning visitors, both outcomes, loading failures and save/progress retries.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For a Portal brand: follow https://franchiseai.github.io/website-integrations/portal.md and the repository example. The experimental Portal adapter is not in npm 0.1.0 and has no live backend integration. Build a clearly labelled, network-free prototype: initial details and optional consent, email/password signup with confirmation, or Google/LinkedIn, then a simulated handoff to the hosted Applicant Portal. Keep password capability. Test provider cancellation, different-email recovery, expired links, returning applicants and retries. Never silently merge identities or treat a client-side success state as authentication.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Match the site&#39;s existing design using fully custom components. Keep one stable controller per enquiry, with accessible labels, errors, focus, progress, back navigation and pending states. Use fake details and a throwaway password in demos; keep passwords and credentials out of saved drafts, browser storage, logs, analytics and recordings.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Run the relevant checks and show me the working prototype. For Funnel, connect live only with the supplied API base URL, published funnel slug or host, and authorization for a live test. For Portal, explain the backend work and supported release still needed; don&#39;t invent endpoints or connect the draft API. Don&#39;t deploy the website automatically.</span></span></code></pre></div></div><div class="prompt-steps"><span><b>01</b> Copy the prompt</span><span><b>02</b> Paste into your coding agent</span><span><b>03</b> Preview it in your site</span></div></section><h2 id="choose-your-integration" tabindex="-1">Choose your integration. <a class="header-anchor" href="#choose-your-integration" aria-label="Permalink to &quot;Choose your integration.&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Brand type</th><th>Start here</th><th>Availability</th></tr></thead><tbody><tr><td>Funnel</td><td><a href="./getting-started.html">React/Astro setup</a> · <a href="/website-integrations/playground/">Playground</a></td><td>npm 0.1.0; demo and live adapters. Verify the published customer configuration before launch.</td></tr><tr><td>Portal</td><td><a href="./portal.html">Enrollment guide</a> · <a href="/website-integrations/playground/?flow=portal">Playground</a></td><td>Repository prototype; password/email, Google and LinkedIn are simulated. Backend work and a supported release are still required.</td></tr></tbody></table><p>For <strong>Funnel brands</strong>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @franchiseai/website-integrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react@^19</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react-dom@^19</span></span></code></pre></div><p>Start with the <a href="./getting-started.html">React/Astro guide</a>, then connect your <a href="./going-live.html">published funnel</a>. The package handles validation, lead capture, configured page saves and server-controlled qualification. You own every pixel.</p><h2 id="built-for-people-and-their-agents" tabindex="-1">Built for people and their agents <a class="header-anchor" href="#built-for-people-and-their-agents" aria-label="Permalink to &quot;Built for people and their agents&quot;">​</a></h2><p>Give your agent <a href="/website-integrations/llms-full.txt">the complete plain-text guide</a>, or install the optional skill:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> franchiseai/website-integrations</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integrate-fsai</span></span></code></pre></div><p>The <a href="/website-integrations/openapi.json">OpenAPI 3.1 document</a> and <a href="/website-integrations/api.html" target="_self">Redoc API reference</a> describe the existing Funnel HTTP endpoints. Portal has a separate <a href="/website-integrations/portal-openapi.draft.json">draft OpenAPI contract</a>; it is not a deployed API. Website developers should generally use the package rather than reimplementing the workflow.</p><p>Version 0.1 covers qualification and secure email continuation. Enquiries are held in memory; provision and verify the customer’s live configuration before shipping. <a href="./contract.html">Read the scope and boundaries</a>.</p><h2 id="portal-brands-too" tabindex="-1">Portal brands, too. <a class="header-anchor" href="#portal-brands-too" aria-label="Permalink to &quot;Portal brands, too.&quot;">​</a></h2><p>Explore <a href="/website-integrations/playground/?flow=portal">the Portal enrollment prototype</a>: custom initial details, email/password or Google/LinkedIn, then a simulated handoff to the hosted Applicant Portal. Try two designs using the same headless integration.</p><p><a href="./portal.html">Read the Portal guide</a> for the flow, agent prompt and backend requirements. This is a repository-only demo; npm 0.1.0 and the live integration still cover Funnel brands.</p>`,14)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
